// AUTO-GENERATED by scripts/build-api-docs.mjs from /docs. Do not edit; run `npm run gen:docs -w aaira-gallery`.
const area: Record<string, Record<string, string>> = {"web-forms-mapping":{"overview":"<div class=\"table-scroll\"><table><thead><tr><th>ASP.NET Web Forms</th><th>TypeScript</th><th>Notes</th></tr></thead><tbody><tr><td><code>&lt;asp:RequiredFieldValidator&gt;</code></td><td><code>RequiredFieldValidatorController</code></td><td><code>InitialValue</code> maps to <code>initialValue</code>.</td></tr><tr><td><code>&lt;asp:CompareValidator&gt;</code></td><td><code>CompareValidatorController</code></td><td><code>ControlToCompare</code>, <code>ValueToCompare</code>, <code>Operator</code>, <code>Type</code>.</td></tr><tr><td><code>&lt;asp:RangeValidator&gt;</code></td><td><code>RangeValidatorController</code></td><td><code>MinimumValue</code>, <code>MaximumValue</code>, <code>Type</code>.</td></tr><tr><td><code>&lt;asp:RegularExpressionValidator&gt;</code></td><td><code>RegularExpressionValidatorController</code></td><td><code>ValidationExpression</code>. JavaScript <code>RegExp</code> syntax, not .NET.</td></tr><tr><td><code>&lt;asp:CustomValidator&gt;</code></td><td><code>CustomValidatorController</code></td><td><code>ClientValidationFunction</code> plus an async <code>serverValidate</code> callback replacing the <code>ServerValidate</code> event.</td></tr><tr><td><code>&lt;asp:ValidationSummary&gt;</code></td><td><code>ValidationSummaryController</code></td><td>Pure formatter; does not run validators.</td></tr><tr><td><code>BaseValidator</code></td><td><code>BaseValidatorController</code> (abstract)</td><td></td></tr><tr><td><code>Page.Validate(group)</code> + <code>Page.IsValid</code></td><td><code>await ValidatorManager.validate(group)</code> / <code>ValidatorManager.isValid(group)</code></td><td></td></tr><tr><td><code>ControlToValidate</code></td><td><code>controlToValidate</code> (a string control id)</td><td>Resolved to a value by <code>ValidatorManager.getControlValue</code>.</td></tr><tr><td><code>ValidationGroup</code></td><td><code>validationGroup</code></td><td><code>&quot;&quot;</code> is the default group.</td></tr><tr><td><code>Enabled</code></td><td><code>enabled</code></td><td></td></tr><tr><td><code>Display=&quot;Static|Dynamic|None&quot;</code></td><td><code>display</code></td><td>Stored only; the core never renders.</td></tr><tr><td><code>SetFocusOnError</code></td><td><code>setFocusOnError</code></td><td>Stored only; the core never focuses anything.</td></tr><tr><td><code>ErrorMessage</code> / <code>Text</code></td><td><code>errorMessage</code> / <code>text</code></td><td>Summary uses <code>errorMessage</code>; inline UI should show <code>text</code>.</td></tr><tr><td><code>ValidationDataType</code></td><td><code>ValidationDataType</code></td><td><code>String</code>, <code>Integer</code>, <code>Double</code>, <code>Date</code>, <code>Currency</code>.</td></tr><tr><td><code>ValidationCompareOperator</code></td><td><code>ValidationCompareOperator</code></td><td><code>Equal</code> ... <code>DataTypeCheck</code>.</td></tr><tr><td><code>ValidationSummaryDisplayMode</code></td><td><code>ValidationSummaryDisplayMode</code></td><td><code>BulletList</code>, <code>List</code>, <code>SingleParagraph</code>.</td></tr></tbody></table></div>\n<hr>\n"},"quick-start":{"overview":"<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">import</span> {\n  <span class=\"tok-t\">ValidatorManager</span>,\n  <span class=\"tok-t\">RequiredFieldValidatorController</span>,\n  <span class=\"tok-t\">ValidationSummaryController</span>\n} <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n\n<span class=\"tok-k\">const</span> form = { user: <span class=\"tok-s\">&quot;&quot;</span>, pass: <span class=\"tok-s\">&quot;&quot;</span> };\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">registerValueAccessor</span>(<span class=\"tok-s\">&quot;txtUser&quot;</span>, () =&gt; form.user);\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">registerValueAccessor</span>(<span class=\"tok-s\">&quot;txtPass&quot;</span>, () =&gt; form.pass);\n\n<span class=\"tok-k\">new</span> <span class=\"tok-t\">RequiredFieldValidatorController</span>({\n  id: <span class=\"tok-s\">&quot;rfvUser&quot;</span>, controlToValidate: <span class=\"tok-s\">&quot;txtUser&quot;</span>,\n  errorMessage: <span class=\"tok-s\">&quot;User name is required.&quot;</span>, validationGroup: <span class=\"tok-s\">&quot;login&quot;</span>\n});\n<span class=\"tok-k\">new</span> <span class=\"tok-t\">RequiredFieldValidatorController</span>({\n  id: <span class=\"tok-s\">&quot;rfvPass&quot;</span>, controlToValidate: <span class=\"tok-s\">&quot;txtPass&quot;</span>,\n  errorMessage: <span class=\"tok-s\">&quot;Password is required.&quot;</span>, validationGroup: <span class=\"tok-s\">&quot;login&quot;</span>\n});\n<span class=\"tok-k\">const</span> summary = <span class=\"tok-k\">new</span> <span class=\"tok-t\">ValidationSummaryController</span>({\n  id: <span class=\"tok-s\">&quot;sum&quot;</span>, validationGroup: <span class=\"tok-s\">&quot;login&quot;</span>, headerText: <span class=\"tok-s\">&quot;Please fix:&quot;</span>\n});\n\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">isValid</span>(<span class=\"tok-s\">&quot;login&quot;</span>));        <span class=\"tok-c\">// -&gt; true   (nothing has run yet)</span>\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> <span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">validate</span>(<span class=\"tok-s\">&quot;login&quot;</span>)); <span class=\"tok-c\">// -&gt; false</span>\nconsole.<span class=\"tok-f\">log</span>(summary.<span class=\"tok-f\">getFormattedErrors</span>());\n<span class=\"tok-c\">// -&gt; Please fix:</span>\n<span class=\"tok-c\">// -&gt; • User name is required.</span>\n<span class=\"tok-c\">// -&gt; • Password is required.</span>\n\nform.user = <span class=\"tok-s\">&quot;bob&quot;</span>; form.pass = <span class=\"tok-s\">&quot;x&quot;</span>;\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> <span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">validate</span>(<span class=\"tok-s\">&quot;login&quot;</span>), summary.<span class=\"tok-f\">getErrorMessages</span>()); <span class=\"tok-c\">// -&gt; true []</span></code></pre></div>\n<hr>\n"},"concepts-and-semantics":{"registration-and-validator-lifetime":"<h3 id=\"31-registration-and-validator-lifetime\">3.1 Registration and validator lifetime<a class=\"anchor\" href=\"#31-registration-and-validator-lifetime\" aria-label=\"Link to this section\">#</a></h3>\n<p>Constructing any validator calls <code>ValidatorManager.register(this)</code>. There is no explicit &quot;add to page&quot; step. Call <code>validator.dispose()</code> to unregister it (for example when a UI component unmounts). <code>ValidatorManager</code> is a process-wide static registry, so tests and SPAs that re-create forms should call <code>dispose()</code> per validator or <code>ValidatorManager.clear()</code> between runs. <code>ValidationSummaryController</code> is not registered anywhere.</p>\n","where-control-values-come-from":"<h3 id=\"32-where-control-values-come-from\">3.2 Where control values come from<a class=\"anchor\" href=\"#32-where-control-values-come-from\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>ValidatorManager.getControlValue(controlId)</code> resolves in this order and stops at the first hit:</p>\n<ol><li>A registered accessor (<code>registerValueAccessor(controlId, fn)</code>) - always wins, even when it returns <code>undefined</code>.</li><li><code>ValidatorManager.globalValueResolver(controlId)</code> - used only if it returns something other than <code>undefined</code>.</li><li>Browser DOM fallback (only when <code>document</code> exists): <code>getElementById(controlId)</code> or <code>[name=&quot;controlId&quot;]</code>. Checkboxes return <code>.checked</code> (boolean); other elements with a <code>value</code> return <code>.value</code>.</li><li><code>&quot;&quot;</code> (empty string).</li></ol>\n<p>An unregistered control therefore reads as <code>&quot;&quot;</code>, which makes a <code>RequiredFieldValidator</code> fail and every other validator pass.</p>\n","validation-groups":"<h3 id=\"33-validation-groups\">3.3 Validation groups<a class=\"anchor\" href=\"#33-validation-groups\" aria-label=\"Link to this section\">#</a></h3>\n<p>A validator belongs to exactly one group, <code>validationGroup</code> (default <code>&quot;&quot;</code>). All manager methods take an optional group; <code>undefined</code> and <code>&quot;&quot;</code> both mean the default group. Matching is strict equality, so <code>&quot;Login&quot;</code> and <code>&quot;login&quot;</code> are different groups and a validator in a named group is never touched by <code>validate()</code> with no argument.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-c\">// va in group &quot;g1&quot;, vb in default group, both fields empty</span>\n<span class=\"tok-k\">await</span> <span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">validate</span>(<span class=\"tok-s\">&quot;g1&quot;</span>);   <span class=\"tok-c\">// -&gt; false  (only va ran)</span>\n<span class=\"tok-k\">await</span> <span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">validate</span>();       <span class=\"tok-c\">// -&gt; false  (only vb ran)</span>\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">isValid</span>(<span class=\"tok-s\">&quot;nope&quot;</span>);        <span class=\"tok-c\">// -&gt; true   (empty group: Array.every on [] is true)</span>\n<span class=\"tok-k\">await</span> <span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">validate</span>(<span class=\"tok-s\">&quot;nope&quot;</span>); <span class=\"tok-c\">// -&gt; true</span></code></pre></div>\n","pageisvalid-simulation":"<h3 id=\"34-pageisvalid-simulation\">3.4 <code>Page_IsValid</code> simulation<a class=\"anchor\" href=\"#34-pageisvalid-simulation\" aria-label=\"Link to this section\">#</a></h3>\n<p>Web Forms keeps <code>Page.IsValid</code> as a derived page flag. Here the equivalent is:</p>\n<ul><li><code>await ValidatorManager.validate(group)</code> - runs every validator in the group <strong>sequentially, in registration order, without short-circuiting</strong> (all validators run even after the first failure, so all messages are populated) and returns <code>true</code> only if all passed. This is the &quot;click the submit button&quot; step.</li><li><code>ValidatorManager.isValid(group)</code> - a <strong>synchronous read</strong> of each validator's cached <code>isValid</code>. It does not run anything. Before the first <code>validate()</code>, every validator is valid, so <code>isValid()</code> is <code>true</code>.</li><li><code>ValidatorManager.reset(group)</code> - sets cached <code>isValid = true</code> for the group (equivalent to clearing error state) without evaluating.</li></ul>\n","when-validators-run":"<h3 id=\"35-when-validators-run\">3.5 When validators run<a class=\"anchor\" href=\"#35-when-validators-run\" aria-label=\"Link to this section\">#</a></h3>\n<p>Nothing validates automatically. Validators run only when you call <code>ValidatorManager.validate(group)</code> or <code>validator.validate()</code>. Wire these to your submit handler (and, if you want on-blur validation, to your change/blur handlers). There is no <code>CausesValidation</code> flag in the core.</p>\n","result-lifecycle-of-a-single-validate":"<h3 id=\"36-result-lifecycle-of-a-single-validate\">3.6 Result lifecycle of a single <code>validate()</code><a class=\"anchor\" href=\"#36-result-lifecycle-of-a-single-validate\" aria-label=\"Link to this section\">#</a></h3>\n<ol><li>If <code>enabled === false</code>: <code>isValid</code> is set to <code>true</code> and <code>true</code> is returned. No events fire.</li><li><code>await validating.emit(...)</code>. A handler that throws here rejects <code>validate()</code> (it is outside the try/catch).</li><li><code>isValid = await evaluateIsValid()</code>. <strong>Any exception thrown by evaluation is swallowed and treated as invalid</strong> (<code>isValid = false</code>).</li><li><code>getControlValue()</code> is read again and <code>await validated.emit({ validator, isValid, value })</code>.</li><li>Returns <code>isValid</code>.</li></ol>\n<p>Gotcha: because step 4 re-reads the control value outside the try/catch, a value accessor that throws makes <code>validate()</code> reject (after <code>isValid</code> was already set to <code>false</code> in step 3).</p>\n","empty-value-rule":"<h3 id=\"37-empty-value-rule\">3.7 Empty-value rule<a class=\"anchor\" href=\"#37-empty-value-rule\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>RequiredFieldValidator</code> is the only validator that fails on empty input. <code>CompareValidator</code>, <code>RangeValidator</code>, and <code>RegularExpressionValidator</code> pass when the value is <code>undefined</code>, <code>null</code>, or whitespace-only; <code>CustomValidator</code> passes it too unless <code>validateEmptyText</code> is <code>true</code>. Pair them with a <code>RequiredFieldValidator</code> when the field is mandatory.</p>\n","errormessage-text-display-setfocusonerror":"<h3 id=\"38-errormessage-text-display-setfocusonerror\">3.8 <code>errorMessage</code>, <code>text</code>, <code>display</code>, <code>setFocusOnError</code><a class=\"anchor\" href=\"#38-errormessage-text-display-setfocusonerror\" aria-label=\"Link to this section\">#</a></h3>\n<ul><li><code>errorMessage</code> defaults to <code>&quot;Input is invalid.&quot;</code>. It is what <code>ValidationSummaryController</code> lists. A validator whose <code>errorMessage</code> is empty or whitespace is silently omitted from the summary.</li><li><code>text</code> defaults to a <strong>copy</strong> of <code>errorMessage</code> as it was at construction time (it is not live-linked; changing <code>errorMessage</code> later does not change <code>text</code>). Use <code>text</code> for the inline message next to the field (<code>&quot;*&quot;</code> is the classic choice).</li><li><code>display</code> (<code>&quot;Static&quot; | &quot;Dynamic&quot; | &quot;None&quot;</code>) and <code>setFocusOnError</code> are plain stored properties. The headless core never reads them; a React/Angular/jQuery adapter or your own UI decides to reserve layout space (<code>Static</code>), collapse (<code>Dynamic</code>), hide (<code>None</code>), and focus the control (<code>setFocusOnError</code>).</li><li>Gotcha: <code>RequiredFieldValidatorController</code> overrides defaults to <code>&quot;This field is required.&quot;</code> only if <strong>neither</strong> <code>errorMessage</code> nor <code>text</code> is supplied. Supplying only <code>text: &quot;*&quot;</code> leaves <code>errorMessage</code> as <code>&quot;Input is invalid.&quot;</code> (verified), so the summary would show the generic message.</li></ul>\n","enable-disable":"<h3 id=\"39-enabledisable\">3.9 Enable/disable<a class=\"anchor\" href=\"#39-enabledisable\" aria-label=\"Link to this section\">#</a></h3>\n<p>Set <code>validator.enabled = false</code> to skip it. Disabling does <strong>not</strong> clear a previously failed state: <code>isValid</code> stays <code>false</code> (and <code>ValidatorManager.isValid(group)</code> stays <code>false</code>, and the summary still lists it) until the next <code>validate()</code> on that validator, which resets it to <code>true</code>, or <code>ValidatorManager.reset(group)</code>.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\">va.enabled = <span class=\"tok-k\">true</span>;  <span class=\"tok-k\">await</span> va.<span class=\"tok-f\">validate</span>();       <span class=\"tok-c\">// field empty -&gt; va.isValid === false</span>\nva.enabled = <span class=\"tok-k\">false</span>;\nva.isValid;                                    <span class=\"tok-c\">// -&gt; false  (stale)</span>\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">isValid</span>(<span class=\"tok-s\">&quot;g1&quot;</span>);                <span class=\"tok-c\">// -&gt; false  (stale)</span>\n<span class=\"tok-k\">await</span> <span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">validate</span>(<span class=\"tok-s\">&quot;g1&quot;</span>);         <span class=\"tok-c\">// disabled validators report true</span>\nva.isValid;                                    <span class=\"tok-c\">// -&gt; true</span></code></pre></div>\n","comparison-operators-and-data-types":"<h3 id=\"310-comparison-operators-and-data-types\">3.10 Comparison operators and data types<a class=\"anchor\" href=\"#310-comparison-operators-and-data-types\" aria-label=\"Link to this section\">#</a></h3>\n<p>Operators (<code>ValidationCompareOperator</code>): <code>Equal</code>, <code>NotEqual</code>, <code>GreaterThan</code>, <code>GreaterThanEqual</code>, <code>LessThan</code>, <code>LessThanEqual</code>, <code>DataTypeCheck</code>.</p>\n<p>Both operands are converted with <code>convert(value, type)</code> before comparing. If either converts to <code>null</code>, the result is <strong>invalid</strong> (<code>false</code>), except for the empty cases below.</p>\n<div class=\"table-scroll\"><table><thead><tr><th><code>ValidationDataType</code></th><th>Conversion rule</th><th>Gotchas (verified)</th></tr></thead><tbody><tr><td><code>String</code></td><td>Trimmed string. Ordinal, <strong>case-sensitive</strong> comparison with JS <code>&lt;</code>/<code>&gt;</code>.</td><td><code>&quot;ABC&quot;</code> vs <code>&quot;abc&quot;</code> with <code>Equal</code> is invalid. <code>&quot;12&quot; &gt; &quot;5&quot;</code> is <code>false</code> (lexicographic).</td></tr><tr><td><code>Integer</code></td><td><code>parseInt(str, 10)</code> accepted only if <code>String(parsed) === str</code> (after trim).</td><td><code>&quot;+5&quot;</code>, <code>&quot;007&quot;</code>, <code>&quot;5.5&quot;</code>, <code>&quot;1e3&quot;</code> are not integers. <code>&quot; 5 &quot;</code> is accepted.</td></tr><tr><td><code>Double</code></td><td><code>parseFloat(str)</code>.</td><td>Lenient: <code>&quot;12abc&quot;</code> parses as <code>12</code>.</td></tr><tr><td><code>Currency</code></td><td>Strips one leading <code>$</code>, <code>£</code> or <code>€</code>, removes all <code>,</code>, then <code>parseFloat</code>.</td><td><code>&quot;$1,200.50&quot;</code> equals <code>&quot;1200.5&quot;</code>. Lenient like <code>Double</code>.</td></tr><tr><td><code>Date</code></td><td><code>new Date(str).getTime()</code> (or <code>getTime()</code> of a <code>Date</code> instance).</td><td>Whatever JS can parse; locale-agnostic ISO strings are safest. <code>&quot;nope&quot;</code> converts to <code>null</code>.</td></tr></tbody></table></div>\n<p>Empty/short-circuit rules for <code>CompareValidator</code>: empty control value passes; for non-<code>DataTypeCheck</code> operators, an empty/absent compare operand (<code>valueToCompare</code> or the other control's value) also passes. <code>DataTypeCheck</code> only checks that the control value converts under <code>type</code> and ignores the operand.</p>\n<p>When <code>controlToCompare</code> is set it takes precedence over <code>valueToCompare</code>.</p>\n","range-types":"<h3 id=\"311-range-types\">3.11 Range types<a class=\"anchor\" href=\"#311-range-types\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>RangeValidatorController</code> converts value, minimum and maximum with the same <code>convert</code> table above and checks the <strong>inclusive</strong> range <code>min &lt;= value &lt;= max</code>. If any of the three converts to <code>null</code> (including a non-numeric bound) it is invalid. <code>type</code> defaults to <code>&quot;String&quot;</code>, which compares ordinally and case-sensitively (<code>&quot;B&quot;</code> is outside <code>&quot;b&quot;..&quot;d&quot;</code>; <code>&quot;dd&quot;</code> is also outside because <code>&quot;dd&quot; &gt; &quot;d&quot;</code>).</p>\n","regular-expression-semantics":"<h3 id=\"312-regular-expression-semantics\">3.12 Regular-expression semantics<a class=\"anchor\" href=\"#312-regular-expression-semantics\" aria-label=\"Link to this section\">#</a></h3>\n<ul><li>The expression is a JavaScript <code>RegExp</code> source string. <strong>There is no flags option</strong>; the validator calls <code>new RegExp(pattern)</code> with no flags, so it is always case-sensitive and inline .NET flags such as <code>(?i)</code> are invalid (they make the regex throw, which the validator reports as invalid).</li><li>Implicit anchoring: unless the pattern starts with <code>^</code> <strong>or</strong> ends with <code>$</code>, it is wrapped as <code>^(?:pattern)$</code> (so <code>a|b</code> matches <code>&quot;b&quot;</code> but not <code>&quot;ab&quot;</code>).</li><li>Gotcha: if the pattern has only one anchor, it is <strong>not wrapped</strong> and is used as-is. <code>&quot;^\\\\d+&quot;</code> matches <code>&quot;123abc&quot;</code> and <code>&quot;\\\\d+$&quot;</code> matches <code>&quot;abc123&quot;</code> (both verified as valid).</li><li>An invalid expression never throws; the validator simply returns <code>false</code>.</li></ul>\n","custom-validator-sync-async-contract":"<h3 id=\"313-custom-validator-syncasync-contract\">3.13 Custom validator sync/async contract<a class=\"anchor\" href=\"#313-custom-validator-syncasync-contract\" aria-label=\"Link to this section\">#</a></h3>\n<p>Evaluation order inside <code>CustomValidatorController.evaluateIsValid()</code> (always async):</p>\n<ol><li>Read the value, <code>String(value)</code> (<code>&quot;&quot;</code> for null/undefined).</li><li>If <code>validateEmptyText</code> is <code>false</code> (default) and the string is blank, return <code>true</code> without calling either callback.</li><li>Build <code>args = { value, isValid: true }</code>.</li><li>If <code>clientValidationFunction</code> is set, call it synchronously. A returned <code>boolean</code> overwrites <code>args.isValid</code>; any other return (including <code>undefined</code>) leaves it alone, so the callback can instead set <code>args.isValid = false</code>. If invalid, return <code>false</code> immediately - <strong><code>serverValidate</code> is not called</strong>.</li><li>If <code>serverValidate</code> is set, <code>await</code> it. A resolved/returned <code>boolean</code> overwrites <code>args.isValid</code>; <code>void</code> leaves it alone (so setting <code>args.isValid</code> works). If invalid, return <code>false</code>.</li><li>Return <code>args.isValid</code>.</li></ol>\n<p>Exceptions or rejections from either callback are caught by the base class and mean <code>isValid = false</code>. Gotcha: an <code>async</code> <code>clientValidationFunction</code> returns a Promise, which is not a <code>boolean</code>, so it is <strong>ignored and treated as valid</strong> (verified). Put asynchronous checks in <code>serverValidate</code>.</p>\n","summary-modes":"<h3 id=\"314-summary-modes\">3.14 Summary modes<a class=\"anchor\" href=\"#314-summary-modes\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Mode</th><th>Output of <code>getFormattedErrors()</code> for messages <code>A</code>, <code>B</code> and header <code>H</code></th></tr></thead><tbody><tr><td><code>BulletList</code> (default)</td><td><code>H\\n• A\\n• B</code></td></tr><tr><td><code>List</code></td><td><code>H\\nA\\nB</code></td></tr><tr><td><code>SingleParagraph</code></td><td><code>H\\nA B</code></td></tr></tbody></table></div>\n<p><code>H\\n</code> is omitted when <code>headerText</code> is empty. With no messages the result is <code>&quot;&quot;</code> (the header is not shown alone). The summary reads current state: it calls <code>ValidatorManager.getInvalidValidators(group)</code>, so it only shows what a previous <code>validate()</code> produced.</p>\n<hr>\n"},"validatormanager":{"overview":"<p>Static registry and orchestrator. Never instantiated. ASP.NET equivalent: <code>Page.Validators</code>, <code>Page.Validate()</code>, <code>Page.IsValid</code>, <code>Page_ClientValidate()</code>.</p>\n","types":"<h3 id=\"types\">Types<a class=\"anchor\" href=\"#types\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Definition</th></tr></thead><tbody><tr><td><code>ControlValueAccessor</code></td><td><code>() =&gt; unknown</code></td></tr><tr><td><code>GlobalValueResolver</code></td><td><code>(controlId: string) =&gt; unknown</code></td></tr></tbody></table></div>\n","static-properties":"<h3 id=\"static-properties\">Static properties<a class=\"anchor\" href=\"#static-properties\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>globalValueResolver</code></td><td><code>GlobalValueResolver | undefined</code></td><td>r/w</td><td><code>undefined</code></td><td>Fallback value source consulted when no accessor is registered. Returning <code>undefined</code> falls through to the DOM fallback. Reset to <code>undefined</code> by <code>clear()</code>.</td></tr></tbody></table></div>\n","static-methods":"<h3 id=\"static-methods\">Static methods<a class=\"anchor\" href=\"#static-methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Parameters</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>register(validator: BaseValidatorController): void</code></td><td><code>validator</code> - validator to add</td><td><code>void</code></td><td>-</td><td>Adds to the registry (a <code>Set</code>, so re-adding is a no-op). Called automatically by the base constructor.</td></tr><tr><td><code>unregister(validator: BaseValidatorController): void</code></td><td><code>validator</code></td><td><code>void</code></td><td>-</td><td>Removes it. Called by <code>validator.dispose()</code>.</td></tr><tr><td><code>registerValueAccessor(controlId: string, accessor: ControlValueAccessor): () =&gt; void</code></td><td><code>controlId</code> - id used in <code>controlToValidate</code>/<code>controlToCompare</code>; <code>accessor</code> - returns current value</td><td>An unsubscribe function that deletes this id's accessor</td><td>-</td><td>Replaces any existing accessor for that id.</td></tr><tr><td><code>getControlValue(controlId: string): unknown</code></td><td><code>controlId</code></td><td>The value (see 3.2); <code>&quot;&quot;</code> if unresolved</td><td>Whatever the accessor/resolver throws</td><td>Resolution: accessor, resolver, DOM, <code>&quot;&quot;</code>.</td></tr><tr><td><code>getValidators(validationGroup?: string): BaseValidatorController[]</code></td><td><code>validationGroup</code> - <code>undefined</code> means <code>&quot;&quot;</code></td><td>New array, registration order</td><td>-</td><td>Validators whose <code>validationGroup</code> equals the argument exactly. Includes disabled ones.</td></tr><tr><td><code>getInvalidValidators(validationGroup?: string): BaseValidatorController[]</code></td><td>as above</td><td>Subset with <code>isValid === false</code></td><td>-</td><td>Cached state; includes disabled validators with stale failure state.</td></tr><tr><td><code>validate(validationGroup?: string): Promise&lt;boolean&gt;</code></td><td>as above</td><td><code>true</code> when every validator in the group passed</td><td>Rejects if a <code>validating</code>/<code>validated</code> handler throws or a value accessor throws</td><td>Runs all validators sequentially without short-circuit.</td></tr><tr><td><code>isValid(validationGroup?: string): boolean</code></td><td>as above</td><td><code>true</code> when all cached <code>isValid</code> are true (or the group is empty)</td><td>-</td><td>Synchronous; does not run validators.</td></tr><tr><td><code>reset(validationGroup?: string): void</code></td><td>as above</td><td><code>void</code></td><td>-</td><td>Sets cached <code>isValid = true</code> for the group. Does not fire events.</td></tr><tr><td><code>clear(): void</code></td><td>-</td><td><code>void</code></td><td>-</td><td>Empties validators and accessors and sets <code>globalValueResolver</code> to <code>undefined</code>. Use between tests.</td></tr></tbody></table></div>\n<p>Events: none. Subscribe on individual validators.</p>\n<hr>\n"},"basevalidatorcontroller-abstract":{"overview":"<p>ASP.NET: <code>System.Web.UI.WebControls.BaseValidator</code>. All concrete validators inherit these members.</p>\n","types":"<h3 id=\"types-1\">Types<a class=\"anchor\" href=\"#types-1\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">type</span> <span class=\"tok-t\">ValidatorDisplay</span> = <span class=\"tok-s\">&quot;Static&quot;</span> | <span class=\"tok-s\">&quot;Dynamic&quot;</span> | <span class=\"tok-s\">&quot;None&quot;</span>;\n\n<span class=\"tok-k\">interface</span> <span class=\"tok-t\">ValidationEventArgs</span> {\n  validator: <span class=\"tok-t\">BaseValidatorController</span>;\n  isValid: boolean;\n  value: unknown;   <span class=\"tok-c\">// the control value re-read after evaluation</span>\n}</code></pre></div>\n","constructor-options-basevalidatoroptions":"<h3 id=\"constructor-options-basevalidatoroptions\">Constructor options (<code>BaseValidatorOptions</code>)<a class=\"anchor\" href=\"#constructor-options-basevalidatoroptions\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code> (required)</td><td>-</td><td>Validator id.</td></tr><tr><td><code>controlToValidate</code></td><td><code>string</code> (required)</td><td>-</td><td>Control id passed to <code>ValidatorManager.getControlValue</code>.</td></tr><tr><td><code>errorMessage</code></td><td><code>string</code></td><td><code>&quot;Input is invalid.&quot;</code></td><td>Message listed by <code>ValidationSummaryController</code>.</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>copy of <code>errorMessage</code></td><td>Inline message.</td></tr><tr><td><code>validationGroup</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Group name.</td></tr><tr><td><code>enabled</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Skip when <code>false</code>.</td></tr><tr><td><code>display</code></td><td><code>ValidatorDisplay</code></td><td><code>&quot;Static&quot;</code></td><td>Stored only.</td></tr><tr><td><code>setFocusOnError</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Stored only.</td></tr></tbody></table></div>\n","properties":"<h3 id=\"properties\">Properties<a class=\"anchor\" href=\"#properties\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>r</td><td>from options</td><td></td></tr><tr><td><code>controlToValidate</code></td><td><code>string</code></td><td>r/w</td><td>from options</td><td></td></tr><tr><td><code>errorMessage</code></td><td><code>string</code></td><td>r/w</td><td>see above</td><td></td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>r/w</td><td>see above</td><td></td></tr><tr><td><code>validationGroup</code></td><td><code>string</code></td><td>r/w</td><td><code>&quot;&quot;</code></td><td>Changing it moves the validator to another group immediately (lookup is by property, not stored per group).</td></tr><tr><td><code>enabled</code></td><td><code>boolean</code></td><td>r/w</td><td><code>true</code></td><td>See 3.9.</td></tr><tr><td><code>display</code></td><td><code>ValidatorDisplay</code></td><td>r/w</td><td><code>&quot;Static&quot;</code></td><td></td></tr><tr><td><code>setFocusOnError</code></td><td><code>boolean</code></td><td>r/w</td><td><code>false</code></td><td></td></tr><tr><td><code>isValid</code></td><td><code>boolean</code></td><td>r/w</td><td><code>true</code></td><td>Result of the last evaluation. Writable, but normally managed by <code>validate()</code>/<code>reset()</code>.</td></tr><tr><td><code>validating</code></td><td><code>EventDispatcher&lt;this, { validator }&gt;</code></td><td>r</td><td>-</td><td>Event, see below.</td></tr><tr><td><code>validated</code></td><td><code>EventDispatcher&lt;this, ValidationEventArgs&gt;</code></td><td>r</td><td>-</td><td>Event, see below.</td></tr></tbody></table></div>\n","methods":"<h3 id=\"methods\">Methods<a class=\"anchor\" href=\"#methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Parameters</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>dispose(): void</code></td><td>-</td><td><code>void</code></td><td>-</td><td>Unregisters from <code>ValidatorManager</code>. Does not clear event handlers.</td></tr><tr><td><code>getControlValue(): unknown</code></td><td>-</td><td>Current value of <code>controlToValidate</code></td><td>accessor errors</td><td>Shortcut for <code>ValidatorManager.getControlValue(this.controlToValidate)</code>.</td></tr><tr><td><code>abstract evaluateIsValid(): boolean | Promise&lt;boolean&gt;</code></td><td>-</td><td>validity</td><td>-</td><td>Implemented by subclasses. Call <code>validate()</code> rather than this, which skips events, <code>enabled</code> and caching.</td></tr><tr><td><code>validate(): Promise&lt;boolean&gt;</code></td><td>-</td><td>Resulting <code>isValid</code></td><td>handler errors, accessor errors (see 3.6)</td><td>Full lifecycle in 3.6.</td></tr></tbody></table></div>\n","events":"<h3 id=\"events\">Events<a class=\"anchor\" href=\"#events\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>EventDispatcher&lt;TSender, TArgs&gt;</code> API: <code>subscribe(handler): () =&gt; void</code> (returns an unsubscribe), <code>emit(sender, args): Promise&lt;void&gt;</code> (awaits handlers sequentially), <code>clear(): void</code>. Handlers receive <code>(sender, args)</code>.</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Event</th><th>Args</th><th>Cancellable</th><th>Raised</th></tr></thead><tbody><tr><td><code>validating</code></td><td><code>{ validator }</code></td><td>No</td><td>Before evaluation, only when <code>enabled</code>.</td></tr><tr><td><code>validated</code></td><td><code>ValidationEventArgs</code></td><td>No</td><td>After evaluation (including evaluation that threw), only when <code>enabled</code>.</td></tr></tbody></table></div>\n<hr>\n"},"requiredfieldvalidatorcontroller":{"overview":"<p>ASP.NET: <code>RequiredFieldValidator</code>. Extends <code>BaseValidatorController</code>.</p>\n","constructor-options-requiredfieldvalidatoroptions":"<h3 id=\"constructor-options-requiredfieldvalidatoroptions\">Constructor options (<code>RequiredFieldValidatorOptions</code>)<a class=\"anchor\" href=\"#constructor-options-requiredfieldvalidatoroptions\" aria-label=\"Link to this section\">#</a></h3>\n<p>All base options plus:</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>initialValue</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>A value that counts as &quot;not filled in&quot;, e.g. a placeholder like <code>&quot;-- select --&quot;</code>.</td></tr></tbody></table></div>\n<p>Default messages: if neither <code>errorMessage</code> nor <code>text</code> is passed, both become <code>&quot;This field is required.&quot;</code>.</p>\n","properties":"<h3 id=\"properties-1\">Properties<a class=\"anchor\" href=\"#properties-1\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>initialValue</code></td><td><code>string</code></td><td>r/w</td><td><code>&quot;&quot;</code></td><td>Compared after trimming both sides.</td></tr></tbody></table></div>\n","methods":"<h3 id=\"methods-1\">Methods<a class=\"anchor\" href=\"#methods-1\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Description</th></tr></thead><tbody><tr><td><code>evaluateIsValid(): boolean</code></td><td>validity</td><td><code>undefined</code>/<code>null</code> -&gt; invalid. <code>boolean</code> -&gt; the boolean itself (an unchecked checkbox is invalid). Otherwise <code>String(value).trim()</code> must be non-empty and different from <code>initialValue.trim()</code>. Numbers are valid (<code>5</code> -&gt; valid).</td></tr></tbody></table></div>\n<p>Events: inherited only.</p>\n<hr>\n"},"comparevalidatorcontroller":{"overview":"<p>ASP.NET: <code>CompareValidator</code>. Extends <code>BaseValidatorController</code>. Semantics in 3.10.</p>\n","types":"<h3 id=\"types-2\">Types<a class=\"anchor\" href=\"#types-2\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">type</span> <span class=\"tok-t\">ValidationCompareOperator</span> =\n  <span class=\"tok-s\">&quot;Equal&quot;</span> | <span class=\"tok-s\">&quot;NotEqual&quot;</span> | <span class=\"tok-s\">&quot;GreaterThan&quot;</span> | <span class=\"tok-s\">&quot;GreaterThanEqual&quot;</span> |\n  <span class=\"tok-s\">&quot;LessThan&quot;</span> | <span class=\"tok-s\">&quot;LessThanEqual&quot;</span> | <span class=\"tok-s\">&quot;DataTypeCheck&quot;</span>;\n<span class=\"tok-k\">type</span> <span class=\"tok-t\">ValidationDataType</span> = <span class=\"tok-s\">&quot;String&quot;</span> | <span class=\"tok-s\">&quot;Integer&quot;</span> | <span class=\"tok-s\">&quot;Double&quot;</span> | <span class=\"tok-s\">&quot;Date&quot;</span> | <span class=\"tok-s\">&quot;Currency&quot;</span>;</code></pre></div>\n","constructor-options-comparevalidatoroptions":"<h3 id=\"constructor-options-comparevalidatoroptions\">Constructor options (<code>CompareValidatorOptions</code>)<a class=\"anchor\" href=\"#constructor-options-comparevalidatoroptions\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>controlToCompare</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Id of another control whose value is the right-hand operand. Wins over <code>valueToCompare</code>.</td></tr><tr><td><code>valueToCompare</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Constant right-hand operand.</td></tr><tr><td><code>operator</code></td><td><code>ValidationCompareOperator</code></td><td><code>&quot;Equal&quot;</code></td><td></td></tr><tr><td><code>type</code></td><td><code>ValidationDataType</code></td><td><code>&quot;String&quot;</code></td><td></td></tr></tbody></table></div>\n","properties":"<h3 id=\"properties-2\">Properties<a class=\"anchor\" href=\"#properties-2\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>controlToCompare</code> (<code>string | undefined</code>), <code>valueToCompare</code> (<code>string | undefined</code>), <code>operator</code>, <code>type</code> - all r/w with the defaults above.</p>\n","methods":"<h3 id=\"methods-2\">Methods<a class=\"anchor\" href=\"#methods-2\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Description</th></tr></thead><tbody><tr><td><code>evaluateIsValid(): boolean</code></td><td>validity</td><td>Empty value passes. <code>DataTypeCheck</code> returns <code>canConvert(value, type)</code>. Otherwise resolves the operand, passes if it is empty, fails if either side does not convert, then applies the operator.</td></tr></tbody></table></div>\n","exported-helper-functions-same-module":"<h3 id=\"exported-helper-functions-same-module\">Exported helper functions (same module)<a class=\"anchor\" href=\"#exported-helper-functions-same-module\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>convert(val: unknown, type: ValidationDataType): string | number | null</code></td><td>Conversion table in 3.10. <code>null</code> means &quot;not convertible&quot; (also for <code>null</code>/<code>undefined</code>/blank). <code>convert(&quot;007&quot;,&quot;Integer&quot;)</code> -&gt; <code>null</code>, <code>convert(&quot;7&quot;,&quot;Integer&quot;)</code> -&gt; <code>7</code>.</td></tr><tr><td><code>canConvert(val: unknown, type: ValidationDataType): boolean</code></td><td><code>convert(...) !== null</code>.</td></tr></tbody></table></div>\n<p>Events: inherited only.</p>\n<hr>\n"},"rangevalidatorcontroller":{"overview":"<p>ASP.NET: <code>RangeValidator</code>. Semantics in 3.11.</p>\n","constructor-options-rangevalidatoroptions":"<h3 id=\"constructor-options-rangevalidatoroptions\">Constructor options (<code>RangeValidatorOptions</code>)<a class=\"anchor\" href=\"#constructor-options-rangevalidatoroptions\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>minimumValue</code></td><td><code>string | number | Date</code> (required)</td><td>-</td><td>Inclusive lower bound.</td></tr><tr><td><code>maximumValue</code></td><td><code>string | number | Date</code> (required)</td><td>-</td><td>Inclusive upper bound.</td></tr><tr><td><code>type</code></td><td><code>ValidationDataType</code></td><td><code>&quot;String&quot;</code></td><td>Gotcha: the default is <code>String</code>, not <code>Integer</code>; numeric ranges need <code>type: &quot;Integer&quot;</code> (or <code>Double</code>/<code>Currency</code>).</td></tr></tbody></table></div>\n","properties":"<h3 id=\"properties-3\">Properties<a class=\"anchor\" href=\"#properties-3\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>minimumValue</code>, <code>maximumValue</code>, <code>type</code> - r/w.</p>\n","methods":"<h3 id=\"methods-3\">Methods<a class=\"anchor\" href=\"#methods-3\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Description</th></tr></thead><tbody><tr><td><code>evaluateIsValid(): boolean</code></td><td>validity</td><td>Empty passes; unconvertible value/bound fails; else <code>min &lt;= value &lt;= max</code>.</td></tr></tbody></table></div>\n<p>Events: inherited only.</p>\n<hr>\n"},"regularexpressionvalidatorcontroller":{"overview":"<p>ASP.NET: <code>RegularExpressionValidator</code>. Semantics in 3.12.</p>\n","constructor-options-regularexpressionvalidatoroptions":"<h3 id=\"constructor-options-regularexpressionvalidatoroptions\">Constructor options (<code>RegularExpressionValidatorOptions</code>)<a class=\"anchor\" href=\"#constructor-options-regularexpressionvalidatoroptions\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>validationExpression</code></td><td><code>string</code> (required)</td><td>-</td><td>JavaScript regex source (no delimiters, no flags).</td></tr></tbody></table></div>\n","properties":"<h3 id=\"properties-4\">Properties<a class=\"anchor\" href=\"#properties-4\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>validationExpression: string</code> (r/w).</p>\n","methods":"<h3 id=\"methods-4\">Methods<a class=\"anchor\" href=\"#methods-4\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Description</th></tr></thead><tbody><tr><td><code>evaluateIsValid(): boolean</code></td><td>validity</td><td><code>undefined</code>/<code>null</code>/blank passes. Applies implicit anchoring (3.12). Compile errors yield <code>false</code>.</td></tr></tbody></table></div>\n<p>Events: inherited only.</p>\n<hr>\n"},"customvalidatorcontroller":{"overview":"<p>ASP.NET: <code>CustomValidator</code> (<code>ClientValidationFunction</code> plus the <code>ServerValidate</code> event). Contract in 3.13.</p>\n","types":"<h3 id=\"types-3\">Types<a class=\"anchor\" href=\"#types-3\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">interface</span> <span class=\"tok-t\">ServerValidateEventArgs</span> { value: string; isValid: boolean; }\n\n<span class=\"tok-k\">type</span> <span class=\"tok-t\">ClientValidationFunction</span> = (\n  source: <span class=\"tok-t\">CustomValidatorController</span>, args: <span class=\"tok-t\">ServerValidateEventArgs</span>\n) =&gt; boolean | <span class=\"tok-k\">void</span> | <span class=\"tok-k\">undefined</span>;\n\n<span class=\"tok-k\">type</span> <span class=\"tok-t\">ServerValidateFunction</span> = (\n  source: <span class=\"tok-t\">CustomValidatorController</span>, args: <span class=\"tok-t\">ServerValidateEventArgs</span>\n) =&gt; <span class=\"tok-t\">Promise</span>&lt;boolean | <span class=\"tok-k\">void</span>&gt; | boolean | <span class=\"tok-k\">void</span>;</code></pre></div>\n","constructor-options-customvalidatoroptions":"<h3 id=\"constructor-options-customvalidatoroptions\">Constructor options (<code>CustomValidatorOptions</code>)<a class=\"anchor\" href=\"#constructor-options-customvalidatoroptions\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>clientValidationFunction</code></td><td><code>ClientValidationFunction</code></td><td><code>undefined</code></td><td>Synchronous check. Must not be async.</td></tr><tr><td><code>serverValidate</code></td><td><code>ServerValidateFunction</code></td><td><code>undefined</code></td><td>Sync or async check (REST call etc.).</td></tr><tr><td><code>validateEmptyText</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Run callbacks even for blank values (<code>ValidateEmptyText</code>).</td></tr></tbody></table></div>\n","properties":"<h3 id=\"properties-5\">Properties<a class=\"anchor\" href=\"#properties-5\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>clientValidationFunction</code>, <code>serverValidate</code> (<code>| undefined</code>), <code>validateEmptyText</code> - all r/w.</p>\n","methods":"<h3 id=\"methods-5\">Methods<a class=\"anchor\" href=\"#methods-5\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Description</th></tr></thead><tbody><tr><td><code>evaluateIsValid(): Promise&lt;boolean&gt;</code></td><td>validity</td><td>Algorithm in 3.13. If neither callback is set the result is <code>true</code>.</td></tr></tbody></table></div>\n<p>Events: inherited only. Note <code>args.value</code> is always a string, even if the accessor returned a number.</p>\n<hr>\n"},"validationsummarycontroller":{"overview":"<p>ASP.NET: <code>ValidationSummary</code>. A formatter over <code>ValidatorManager.getInvalidValidators(validationGroup)</code>. It does not register, validate, or subscribe to anything; call it after <code>validate()</code>.</p>\n","types":"<h3 id=\"types-4\">Types<a class=\"anchor\" href=\"#types-4\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">type</span> <span class=\"tok-t\">ValidationSummaryDisplayMode</span> = <span class=\"tok-s\">&quot;BulletList&quot;</span> | <span class=\"tok-s\">&quot;List&quot;</span> | <span class=\"tok-s\">&quot;SingleParagraph&quot;</span>;</code></pre></div>\n","constructor-options-validationsummaryoptions":"<h3 id=\"constructor-options-validationsummaryoptions\">Constructor options (<code>ValidationSummaryOptions</code>)<a class=\"anchor\" href=\"#constructor-options-validationsummaryoptions\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code> (required)</td><td>-</td><td></td></tr><tr><td><code>validationGroup</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Group to summarize.</td></tr><tr><td><code>headerText</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Line printed before the messages.</td></tr><tr><td><code>displayMode</code></td><td><code>ValidationSummaryDisplayMode</code></td><td><code>&quot;BulletList&quot;</code></td><td>See 3.14.</td></tr><tr><td><code>showSummary</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Stored only; adapters decide whether to render.</td></tr><tr><td><code>showMessageBox</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Used by <code>showPopupIfConfigured</code>.</td></tr></tbody></table></div>\n","properties":"<h3 id=\"properties-6\">Properties<a class=\"anchor\" href=\"#properties-6\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>r</td><td>-</td></tr><tr><td><code>validationGroup</code></td><td><code>string</code></td><td>r/w</td><td><code>&quot;&quot;</code></td></tr><tr><td><code>headerText</code></td><td><code>string</code></td><td>r/w</td><td><code>&quot;&quot;</code></td></tr><tr><td><code>displayMode</code></td><td><code>ValidationSummaryDisplayMode</code></td><td>r/w</td><td><code>&quot;BulletList&quot;</code></td></tr><tr><td><code>showSummary</code></td><td><code>boolean</code></td><td>r/w</td><td><code>true</code></td></tr><tr><td><code>showMessageBox</code></td><td><code>boolean</code></td><td>r/w</td><td><code>false</code></td></tr></tbody></table></div>\n","methods":"<h3 id=\"methods-6\">Methods<a class=\"anchor\" href=\"#methods-6\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>getErrorMessages(): string[]</code></td><td>Messages of invalid validators in registration order</td><td>-</td><td>Skips validators whose <code>errorMessage</code> is blank. Includes disabled validators whose stale state is invalid.</td></tr><tr><td><code>getFormattedErrors(): string</code></td><td>Formatted text; <code>&quot;&quot;</code> if no messages</td><td>-</td><td>Uses <code>displayMode</code> and <code>headerText</code>. Newlines are <code>\\n</code>; the bullet is <code>•</code> (U+2022).</td></tr><tr><td><code>showPopupIfConfigured(): void</code></td><td><code>void</code></td><td>-</td><td>Calls <code>window.alert(getFormattedErrors())</code> only if <code>showMessageBox</code> is true, <code>window.alert</code> exists, and the text is non-empty. A silent no-op in Node.</td></tr></tbody></table></div>\n<p>Events: none.</p>\n<hr>\n"},"examples":{"examples":"<p>All examples assume <code>import * as wf from &quot;@wf-controls/core&quot;</code> names, <code>ValidatorManager.clear()</code> at the start, and an ES module (top-level <code>await</code>).</p>\n<ul class=\"aa-doc-index\"><li><a href=\"#/api/validation/examples/examples/example-1---login-form-with-a-validation-group\">Example 1 - Login form with a validation group</a></li><li><a href=\"#/api/validation/examples/examples/example-2---cross-field-compare-confirm-password\">Example 2 - Cross-field compare (confirm password)</a></li><li><a href=\"#/api/validation/examples/examples/example-3---data-type-check-and-typed-comparisons\">Example 3 - Data type check and typed comparisons</a></li><li><a href=\"#/api/validation/examples/examples/example-4---async-custom-validator-username-availability\">Example 4 - Async custom validator (username availability)</a></li><li><a href=\"#/api/validation/examples/examples/example-5---range-validators-integer-date-currency-string\">Example 5 - Range validators (Integer, Date, Currency, String)</a></li><li><a href=\"#/api/validation/examples/examples/example-6---regular-expressions-and-implicit-anchoring\">Example 6 - Regular expressions and implicit anchoring</a></li><li><a href=\"#/api/validation/examples/examples/example-7---requiredfield-with-initialvalue-checkbox-and-number-values\">Example 7 - RequiredField with initialValue, checkbox and number values</a></li><li><a href=\"#/api/validation/examples/examples/example-8---summary-modes-popup-and-reset\">Example 8 - Summary modes, popup, and reset</a></li><li><a href=\"#/api/validation/examples/examples/example-9---groups-enabledisable-events-dispose\">Example 9 - Groups, enable/disable, events, dispose</a></li><li><a href=\"#/api/validation/examples/examples/example-10---value-resolution-order\">Example 10 - Value resolution order</a></li></ul><h3 id=\"example-1---login-form-with-a-validation-group\">Example 1 - Login form with a validation group<a class=\"anchor\" href=\"#example-1---login-form-with-a-validation-group\" aria-label=\"Link to this section\">#</a></h3>\n<p>See the Quick Start (section 2). Output verified:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">text</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-\">before: true\nvalidate: false\nisValid: false\nPlease fix:\n• User name is required.\n• Password is required.\nvalidate2: true []</code></pre></div>\n<h3 id=\"example-2---cross-field-compare-confirm-password\">Example 2 - Cross-field compare (confirm password)<a class=\"anchor\" href=\"#example-2---cross-field-compare-confirm-password\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> f = { pw: <span class=\"tok-s\">&quot;Secret1&quot;</span>, pw2: <span class=\"tok-s\">&quot;Secret2&quot;</span> };\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">registerValueAccessor</span>(<span class=\"tok-s\">&quot;pw&quot;</span>,  () =&gt; f.pw);\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">registerValueAccessor</span>(<span class=\"tok-s\">&quot;pw2&quot;</span>, () =&gt; f.pw2);\n<span class=\"tok-k\">const</span> cv = <span class=\"tok-k\">new</span> <span class=\"tok-t\">CompareValidatorController</span>({\n  id: <span class=\"tok-s\">&quot;cv&quot;</span>, controlToValidate: <span class=\"tok-s\">&quot;pw2&quot;</span>, controlToCompare: <span class=\"tok-s\">&quot;pw&quot;</span>,\n  operator: <span class=\"tok-s\">&quot;Equal&quot;</span>, errorMessage: <span class=\"tok-s\">&quot;Passwords do not match.&quot;</span>\n});\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> <span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">validate</span>(), cv.isValid); <span class=\"tok-c\">// -&gt; false false</span>\nf.pw2 = <span class=\"tok-s\">&quot;Secret1&quot;</span>;\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> <span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">validate</span>(), cv.isValid); <span class=\"tok-c\">// -&gt; true true</span>\nf.pw2 = <span class=\"tok-s\">&quot;&quot;</span>;\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> cv.<span class=\"tok-f\">validate</span>());                           <span class=\"tok-c\">// -&gt; true  (empty passes)</span></code></pre></div>\n<h3 id=\"example-3---data-type-check-and-typed-comparisons\">Example 3 - Data type check and typed comparisons<a class=\"anchor\" href=\"#example-3---data-type-check-and-typed-comparisons\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> f = { v: <span class=\"tok-s\">&quot;abc&quot;</span> };\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">registerValueAccessor</span>(<span class=\"tok-s\">&quot;v&quot;</span>, () =&gt; f.v);\n<span class=\"tok-k\">const</span> dt = <span class=\"tok-k\">new</span> <span class=\"tok-t\">CompareValidatorController</span>({\n  id: <span class=\"tok-s\">&quot;dt&quot;</span>, controlToValidate: <span class=\"tok-s\">&quot;v&quot;</span>, operator: <span class=\"tok-s\">&quot;DataTypeCheck&quot;</span>, <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;Integer&quot;</span>\n});\n<span class=\"tok-k\">await</span> dt.<span class=\"tok-f\">validate</span>();                       <span class=\"tok-c\">// &quot;abc&quot; -&gt; false</span>\nf.v = <span class=\"tok-s\">&quot;12&quot;</span>; <span class=\"tok-k\">await</span> dt.<span class=\"tok-f\">validate</span>();           <span class=\"tok-c\">// -&gt; true</span>\ndt.operator = <span class=\"tok-s\">&quot;GreaterThan&quot;</span>; dt.valueToCompare = <span class=\"tok-s\">&quot;5&quot;</span>;\n<span class=\"tok-k\">await</span> dt.<span class=\"tok-f\">validate</span>();                       <span class=\"tok-c\">// Integer 12 &gt; 5 -&gt; true</span>\ndt.<span class=\"tok-k\">type</span> = <span class=\"tok-s\">&quot;String&quot;</span>;\n<span class=\"tok-k\">await</span> dt.<span class=\"tok-f\">validate</span>();                       <span class=\"tok-c\">// &quot;12&quot; &gt; &quot;5&quot; as strings -&gt; false</span>\ndt.<span class=\"tok-k\">type</span> = <span class=\"tok-s\">&quot;Currency&quot;</span>; f.v = <span class=\"tok-s\">&quot;$1,200.50&quot;</span>; dt.operator = <span class=\"tok-s\">&quot;Equal&quot;</span>; dt.valueToCompare = <span class=\"tok-s\">&quot;1200.5&quot;</span>;\n<span class=\"tok-k\">await</span> dt.<span class=\"tok-f\">validate</span>();                       <span class=\"tok-c\">// -&gt; true</span>\nf.v = <span class=\"tok-s\">&quot;+5&quot;</span>; dt.<span class=\"tok-k\">type</span> = <span class=\"tok-s\">&quot;Integer&quot;</span>; dt.valueToCompare = <span class=\"tok-s\">&quot;5&quot;</span>;\n<span class=\"tok-k\">await</span> dt.<span class=\"tok-f\">validate</span>();                       <span class=\"tok-c\">// -&gt; false (&quot;+5&quot; is not a canonical integer)</span></code></pre></div>\n<h3 id=\"example-4---async-custom-validator-username-availability\">Example 4 - Async custom validator (username availability)<a class=\"anchor\" href=\"#example-4---async-custom-validator-username-availability\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> f = { name: <span class=\"tok-s\">&quot;admin&quot;</span> };\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">registerValueAccessor</span>(<span class=\"tok-s\">&quot;n&quot;</span>, () =&gt; f.name);\n<span class=\"tok-k\">const</span> taken = <span class=\"tok-k\">new</span> <span class=\"tok-t\">Set</span>([<span class=\"tok-s\">&quot;admin&quot;</span>, <span class=\"tok-s\">&quot;root&quot;</span>]);\n<span class=\"tok-k\">const</span> cu = <span class=\"tok-k\">new</span> <span class=\"tok-t\">CustomValidatorController</span>({\n  id: <span class=\"tok-s\">&quot;cu&quot;</span>, controlToValidate: <span class=\"tok-s\">&quot;n&quot;</span>, errorMessage: <span class=\"tok-s\">&quot;Name taken.&quot;</span>,\n  clientValidationFunction: (_s, a) =&gt; a.value.length &gt;= <span class=\"tok-n\">3</span>,       <span class=\"tok-c\">// cheap sync check first</span>\n  serverValidate: <span class=\"tok-k\">async</span> (_s, a) =&gt; {                               <span class=\"tok-c\">// only runs if the sync check passed</span>\n    <span class=\"tok-k\">await</span> <span class=\"tok-k\">new</span> <span class=\"tok-t\">Promise</span>(r =&gt; <span class=\"tok-f\">setTimeout</span>(r, <span class=\"tok-n\">10</span>));                     <span class=\"tok-c\">// pretend HTTP call</span>\n    <span class=\"tok-k\">return</span> !taken.<span class=\"tok-f\">has</span>(a.value);\n  }\n});\ncu.validated.<span class=\"tok-f\">subscribe</span>((_s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;validated&quot;</span>, e.isValid, <span class=\"tok-t\">JSON</span>.<span class=\"tok-f\">stringify</span>(e.value)));\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> cu.<span class=\"tok-f\">validate</span>());   <span class=\"tok-c\">// validated false &quot;admin&quot;  -&gt; false</span>\nf.name = <span class=\"tok-s\">&quot;al&quot;</span>;    console.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> cu.<span class=\"tok-f\">validate</span>()); <span class=\"tok-c\">// validated false &quot;al&quot; -&gt; false (server not called)</span>\nf.name = <span class=\"tok-s\">&quot;alice&quot;</span>; console.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> cu.<span class=\"tok-f\">validate</span>()); <span class=\"tok-c\">// validated true &quot;alice&quot; -&gt; true</span>\nf.name = <span class=\"tok-s\">&quot;&quot;</span>;      console.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> cu.<span class=\"tok-f\">validate</span>()); <span class=\"tok-c\">// validated true &quot;&quot;  -&gt; true (empty skipped)</span></code></pre></div>\n<p>Callback return styles (all verified): a <code>clientValidationFunction</code> that does <code>a.isValid = false</code> and returns nothing fails; an <code>async</code> client function is ignored (treated valid); a <code>serverValidate</code> that throws fails; a <code>serverValidate</code> that sets <code>a.isValid = false</code> fails.</p>\n<h3 id=\"example-5---range-validators-integer-date-currency-string\">Example 5 - Range validators (Integer, Date, Currency, String)<a class=\"anchor\" href=\"#example-5---range-validators-integer-date-currency-string\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> f = { v: <span class=\"tok-s\">&quot;5&quot;</span> };\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">registerValueAccessor</span>(<span class=\"tok-s\">&quot;v&quot;</span>, () =&gt; f.v);\n<span class=\"tok-k\">const</span> r = <span class=\"tok-k\">new</span> <span class=\"tok-t\">RangeValidatorController</span>({\n  id: <span class=\"tok-s\">&quot;r&quot;</span>, controlToValidate: <span class=\"tok-s\">&quot;v&quot;</span>, minimumValue: <span class=\"tok-n\">1</span>, maximumValue: <span class=\"tok-n\">10</span>, <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;Integer&quot;</span>\n});\n<span class=\"tok-c\">// &quot;5&quot; true | &quot;1&quot; true | &quot;10&quot; true | &quot;11&quot; false | &quot;0&quot; false | &quot;abc&quot; false | &quot;&quot; true | &quot;5.5&quot; false</span>\n\n<span class=\"tok-k\">const</span> rd = <span class=\"tok-k\">new</span> <span class=\"tok-t\">RangeValidatorController</span>({\n  id: <span class=\"tok-s\">&quot;rd&quot;</span>, controlToValidate: <span class=\"tok-s\">&quot;v&quot;</span>,\n  minimumValue: <span class=\"tok-s\">&quot;2024-01-01&quot;</span>, maximumValue: <span class=\"tok-k\">new</span> <span class=\"tok-t\">Date</span>(<span class=\"tok-s\">&quot;2024-12-31&quot;</span>), <span class=\"tok-k\">type</span>: <span class=\"tok-s\">&quot;Date&quot;</span>\n});\n<span class=\"tok-c\">// &quot;2024-06-01&quot; true | &quot;2025-01-01&quot; false | &quot;nope&quot; false</span>\n\n<span class=\"tok-k\">const</span> rs = <span class=\"tok-k\">new</span> <span class=\"tok-t\">RangeValidatorController</span>({\n  id: <span class=\"tok-s\">&quot;rs&quot;</span>, controlToValidate: <span class=\"tok-s\">&quot;v&quot;</span>, minimumValue: <span class=\"tok-s\">&quot;b&quot;</span>, maximumValue: <span class=\"tok-s\">&quot;d&quot;</span>   <span class=\"tok-c\">// type defaults to &quot;String&quot;</span>\n});\n<span class=\"tok-c\">// &quot;c&quot; true | &quot;a&quot; false | &quot;B&quot; false | &quot;dd&quot; false</span></code></pre></div>\n<h3 id=\"example-6---regular-expressions-and-implicit-anchoring\">Example 6 - Regular expressions and implicit anchoring<a class=\"anchor\" href=\"#example-6---regular-expressions-and-implicit-anchoring\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> f = { v: <span class=\"tok-s\">&quot;abc123&quot;</span> };\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">registerValueAccessor</span>(<span class=\"tok-s\">&quot;v&quot;</span>, () =&gt; f.v);\n<span class=\"tok-k\">const</span> x = <span class=\"tok-k\">new</span> <span class=\"tok-t\">RegularExpressionValidatorController</span>({\n  id: <span class=\"tok-s\">&quot;x&quot;</span>, controlToValidate: <span class=\"tok-s\">&quot;v&quot;</span>, validationExpression: <span class=\"tok-s\">&quot;[a-z]+\\\\d+&quot;</span>\n});\n<span class=\"tok-k\">await</span> x.<span class=\"tok-f\">validate</span>();                         <span class=\"tok-c\">// &quot;abc123&quot;  -&gt; true</span>\nf.v = <span class=\"tok-s\">&quot;abc123!&quot;</span>; <span class=\"tok-k\">await</span> x.<span class=\"tok-f\">validate</span>();        <span class=\"tok-c\">// -&gt; false (whole-string match)</span>\nx.validationExpression = <span class=\"tok-s\">&quot;a|b&quot;</span>;\nf.v = <span class=\"tok-s\">&quot;b&quot;</span>;  <span class=\"tok-k\">await</span> x.<span class=\"tok-f\">validate</span>();             <span class=\"tok-c\">// -&gt; true</span>\nf.v = <span class=\"tok-s\">&quot;ab&quot;</span>; <span class=\"tok-k\">await</span> x.<span class=\"tok-f\">validate</span>();             <span class=\"tok-c\">// -&gt; false  (wrapped as ^(?:a|b)$)</span>\nx.validationExpression = <span class=\"tok-s\">&quot;^\\\\d+&quot;</span>; f.v = <span class=\"tok-s\">&quot;123abc&quot;</span>;\n<span class=\"tok-k\">await</span> x.<span class=\"tok-f\">validate</span>();                         <span class=\"tok-c\">// -&gt; true   (gotcha: single anchor =&gt; not wrapped)</span>\nx.validationExpression = <span class=\"tok-s\">&quot;(?i)abc&quot;</span>; f.v = <span class=\"tok-s\">&quot;abc&quot;</span>;\n<span class=\"tok-k\">await</span> x.<span class=\"tok-f\">validate</span>();                         <span class=\"tok-c\">// -&gt; false  (.NET inline flag is invalid in JS)</span>\nx.validationExpression = <span class=\"tok-s\">&quot;[a-z&quot;</span>;            <span class=\"tok-c\">// invalid regex</span>\n<span class=\"tok-k\">await</span> x.<span class=\"tok-f\">validate</span>();                         <span class=\"tok-c\">// -&gt; false  (no exception)</span></code></pre></div>\n<h3 id=\"example-7---requiredfield-with-initialvalue-checkbox-and-number-values\">Example 7 - RequiredField with <code>initialValue</code>, checkbox and number values<a class=\"anchor\" href=\"#example-7---requiredfield-with-initialvalue-checkbox-and-number-values\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> f = { a: <span class=\"tok-s\">&quot;&quot;</span>, c: <span class=\"tok-s\">&quot;-- select --&quot;</span>, chk: <span class=\"tok-k\">false</span>, d: <span class=\"tok-n\">5</span> };\n<span class=\"tok-k\">for</span> (<span class=\"tok-k\">const</span> k <span class=\"tok-k\">of</span> <span class=\"tok-t\">Object</span>.<span class=\"tok-f\">keys</span>(f)) <span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">registerValueAccessor</span>(k, () =&gt; f[k]);\n<span class=\"tok-k\">const</span> mk = (id, ctl, o = {}) =&gt; <span class=\"tok-k\">new</span> <span class=\"tok-t\">RequiredFieldValidatorController</span>({ id, controlToValidate: ctl, ...o });\n<span class=\"tok-k\">const</span> a  = <span class=\"tok-f\">mk</span>(<span class=\"tok-s\">&quot;a&quot;</span>, <span class=\"tok-s\">&quot;a&quot;</span>);\n<span class=\"tok-k\">const</span> c  = <span class=\"tok-f\">mk</span>(<span class=\"tok-s\">&quot;c&quot;</span>, <span class=\"tok-s\">&quot;c&quot;</span>, { initialValue: <span class=\"tok-s\">&quot;-- select --&quot;</span>, errorMessage: <span class=\"tok-s\">&quot;Pick one&quot;</span>, text: <span class=\"tok-s\">&quot;!&quot;</span> });\n<span class=\"tok-k\">const</span> k  = <span class=\"tok-f\">mk</span>(<span class=\"tok-s\">&quot;k&quot;</span>, <span class=\"tok-s\">&quot;chk&quot;</span>, { errorMessage: <span class=\"tok-s\">&quot;Accept terms&quot;</span> });\n<span class=\"tok-k\">const</span> u  = <span class=\"tok-f\">mk</span>(<span class=\"tok-s\">&quot;u&quot;</span>, <span class=\"tok-s\">&quot;never-registered&quot;</span>);\n<span class=\"tok-k\">const</span> dd = <span class=\"tok-f\">mk</span>(<span class=\"tok-s\">&quot;dd&quot;</span>, <span class=\"tok-s\">&quot;d&quot;</span>);\n<span class=\"tok-c\">// a false | c false | k false | u false | dd true      (a.errorMessage === &quot;This field is required.&quot;)</span>\nf.chk = <span class=\"tok-k\">true</span>; <span class=\"tok-k\">await</span> k.<span class=\"tok-f\">validate</span>();   <span class=\"tok-c\">// -&gt; true</span></code></pre></div>\n<h3 id=\"example-8---summary-modes-popup-and-reset\">Example 8 - Summary modes, popup, and reset<a class=\"anchor\" href=\"#example-8---summary-modes-popup-and-reset\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-c\">// With three invalid required-field validators (&quot;This field is required.&quot;, &quot;Pick one&quot;, &quot;This field is required.&quot;)</span>\n<span class=\"tok-k\">new</span> <span class=\"tok-t\">ValidationSummaryController</span>({ id: <span class=\"tok-s\">&quot;s&quot;</span>, displayMode: <span class=\"tok-s\">&quot;BulletList&quot;</span>,      headerText: <span class=\"tok-s\">&quot;Errors:&quot;</span> }).<span class=\"tok-f\">getFormattedErrors</span>();\n<span class=\"tok-c\">// -&gt; &quot;Errors:\\n• This field is required.\\n• Pick one\\n• This field is required.&quot;</span>\n<span class=\"tok-c\">// displayMode &quot;List&quot;            -&gt; &quot;Errors:\\nThis field is required.\\nPick one\\nThis field is required.&quot;</span>\n<span class=\"tok-c\">// displayMode &quot;SingleParagraph&quot; -&gt; &quot;Errors:\\nThis field is required. Pick one This field is required.&quot;</span>\n\n<span class=\"tok-c\">// Popup: in a browser window.alert is called with the &quot;List&quot;-formatted text</span>\n<span class=\"tok-k\">new</span> <span class=\"tok-t\">ValidationSummaryController</span>({ id: <span class=\"tok-s\">&quot;p&quot;</span>, showMessageBox: <span class=\"tok-k\">true</span>, displayMode: <span class=\"tok-s\">&quot;List&quot;</span> }).<span class=\"tok-f\">showPopupIfConfigured</span>();\n<span class=\"tok-c\">// ALERT: &quot;This field is required.\\nPick one\\nThis field is required.&quot;   (no-op where window is undefined)</span>\n\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">reset</span>();\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">isValid</span>();                    <span class=\"tok-c\">// -&gt; true</span>\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">getInvalidValidators</span>().length <span class=\"tok-c\">// -&gt; 0</span></code></pre></div>\n<h3 id=\"example-9---groups-enabledisable-events-dispose\">Example 9 - Groups, enable/disable, events, dispose<a class=\"anchor\" href=\"#example-9---groups-enabledisable-events-dispose\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> va = <span class=\"tok-k\">new</span> <span class=\"tok-t\">RequiredFieldValidatorController</span>({ id: <span class=\"tok-s\">&quot;va&quot;</span>, controlToValidate: <span class=\"tok-s\">&quot;a&quot;</span>, validationGroup: <span class=\"tok-s\">&quot;g1&quot;</span> });\n<span class=\"tok-k\">const</span> vb = <span class=\"tok-k\">new</span> <span class=\"tok-t\">RequiredFieldValidatorController</span>({ id: <span class=\"tok-s\">&quot;vb&quot;</span>, controlToValidate: <span class=\"tok-s\">&quot;b&quot;</span> });\n<span class=\"tok-c\">// both fields empty</span>\n<span class=\"tok-k\">await</span> <span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">validate</span>(<span class=\"tok-s\">&quot;g1&quot;</span>);     <span class=\"tok-c\">// -&gt; false</span>\n<span class=\"tok-k\">await</span> <span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">validate</span>();         <span class=\"tok-c\">// -&gt; false</span>\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">getValidators</span>(<span class=\"tok-k\">undefined</span>).<span class=\"tok-f\">map</span>(v =&gt; v.id); <span class=\"tok-c\">// -&gt; [&quot;vb&quot;]</span>\n\nva.enabled = <span class=\"tok-k\">false</span>;\n<span class=\"tok-k\">await</span> va.<span class=\"tok-f\">validate</span>();                       <span class=\"tok-c\">// -&gt; true, va.isValid === true (no events)</span>\nva.enabled = <span class=\"tok-k\">true</span>;\n<span class=\"tok-k\">const</span> order: string[] = [];\nva.validating.<span class=\"tok-f\">subscribe</span>(() =&gt; { order.<span class=\"tok-f\">push</span>(<span class=\"tok-s\">&quot;validating&quot;</span>); });\nva.validated.<span class=\"tok-f\">subscribe</span>((_s, e) =&gt; { order.<span class=\"tok-f\">push</span>(<span class=\"tok-s\">&quot;validated:&quot;</span> + e.isValid); });\n<span class=\"tok-k\">await</span> va.<span class=\"tok-f\">validate</span>();\nconsole.<span class=\"tok-f\">log</span>(order);                        <span class=\"tok-c\">// -&gt; [ 'validating', 'validated:false' ]</span>\n\nva.<span class=\"tok-f\">dispose</span>();\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">getValidators</span>(<span class=\"tok-s\">&quot;g1&quot;</span>).length; <span class=\"tok-c\">// -&gt; 0</span></code></pre></div>\n<h3 id=\"example-10---value-resolution-order\">Example 10 - Value resolution order<a class=\"anchor\" href=\"#example-10---value-resolution-order\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> un = <span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">registerValueAccessor</span>(<span class=\"tok-s\">&quot;zz&quot;</span>, () =&gt; <span class=\"tok-s\">&quot;Z&quot;</span>);\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">getControlValue</span>(<span class=\"tok-s\">&quot;zz&quot;</span>);              <span class=\"tok-c\">// -&gt; &quot;Z&quot;</span>\n<span class=\"tok-f\">un</span>();\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">getControlValue</span>(<span class=\"tok-s\">&quot;zz&quot;</span>);              <span class=\"tok-c\">// -&gt; &quot;&quot;   (accessor removed, nothing else)</span>\n\n<span class=\"tok-t\">ValidatorManager</span>.globalValueResolver = (id) =&gt; ({ q: <span class=\"tok-s\">&quot;Q&quot;</span> } <span class=\"tok-k\">as</span> <span class=\"tok-t\">Record</span>&lt;string, string&gt;)[id];\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">getControlValue</span>(<span class=\"tok-s\">&quot;q&quot;</span>);               <span class=\"tok-c\">// -&gt; &quot;Q&quot;</span>\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">getControlValue</span>(<span class=\"tok-s\">&quot;other&quot;</span>);           <span class=\"tok-c\">// -&gt; &quot;&quot;   (resolver returned undefined)</span>\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">registerValueAccessor</span>(<span class=\"tok-s\">&quot;q&quot;</span>, () =&gt; <span class=\"tok-s\">&quot;acc&quot;</span>);\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">getControlValue</span>(<span class=\"tok-s\">&quot;q&quot;</span>);               <span class=\"tok-c\">// -&gt; &quot;acc&quot; (accessor beats resolver)</span>\n<span class=\"tok-t\">ValidatorManager</span>.<span class=\"tok-f\">clear</span>();                            <span class=\"tok-c\">// resolver -&gt; undefined, no validators</span></code></pre></div>\n<hr>\n"},"gotchas-checklist":{"overview":"<ul><li>Nothing auto-validates; call <code>ValidatorManager.validate(group)</code> yourself.</li><li><code>isValid(group)</code> reads cached state; <code>true</code> before any validation and for unknown groups.</li><li>Disabling a failed validator leaves it failed until re-validated or <code>reset</code>.</li><li><code>text</code> is copied from <code>errorMessage</code> once, at construction.</li><li>Supplying only <code>text</code> on <code>RequiredFieldValidator</code> leaves <code>errorMessage</code> as <code>&quot;Input is invalid.&quot;</code>.</li><li><code>RangeValidator.type</code> defaults to <code>String</code> (ordinal compare), not numeric.</li><li><code>Double</code>/<code>Currency</code> conversions use lenient <code>parseFloat</code> (<code>&quot;12abc&quot;</code> -&gt; 12).</li><li>Regex: JS syntax, no flags, single-anchor patterns are not wrapped, invalid patterns return invalid silently.</li><li><code>async</code> <code>clientValidationFunction</code> is ignored (valid); use <code>serverValidate</code> for async.</li><li><code>display</code> and <code>setFocusOnError</code> are not acted on by the core.</li><li>The validator registry is global; call <code>dispose()</code>/<code>ValidatorManager.clear()</code> to avoid leaks and cross-test contamination.</li></ul>"}};
export default area;
